/* ---------- whiteboard helpers ---------- */
const head = (o: T3, y = 60, size = 38, c = "b") => A.tx(L(o), 400, y, size, c);
/* a word with its ending in colour: the stem ends at x, the ending starts at x */
const end2 = (stem: string, ending: string, x: number, y: number, size = 40, c = "r"): Draw[] => [A.tx(stem, x, y, size, "k", "end"), A.tx(ending, x + 2, y, size, c, "start")];
const Q = (h: T3, ...rest: Draw[]): Draw[] => [A.wipe(), A.tx(L(h), 400, 80, 34, "b"), ...rest];
/* a multiple-choice problem with exactly three distinct options, and a written one */
const choice = (right: string, wrong: string[], show: string, q: Draw[], sol: Draw[], hint: T3): Problem => {
  const opts = shuffle([right, ...wrong.slice(0, 2)]);
  return {kind: "choice", opts, ans: opts.indexOf(right), show, q, sol, hint: {say: hint, draw: []}};
};
const written = (ans: string[], show: string, q: Draw[], sol: Draw[], hint: T3): Problem => ({kind: "text", ans, show, q, sol, hint: {say: hint, draw: []}});

